{"path": "textutils.py", "content": "import re
from collections import Counter

# A word is a run of letters, digits and apostrophes (underscore excluded).
_WORD_RE = re.compile(r"(?:[^\W_]|')+")


def words(text):
    return text.split()


def word_count(text):
    """Return a dict mapping lower-cased words to how often they occur.

    Words are runs of letters, digits and apostrophes; everything else is
    treated as a separator. Apostrophes at the edges of a word (quotes) are
    stripped, and runs made only of apostrophes are ignored.
    """
    counts = Counter()
    for match in _WORD_RE.findall(text.lower()):
        word = match.strip("'")
        if word:
            counts[word] += 1
    return dict(counts)
"}

{"path": "test_textutils.py", "content": "import unittest
from textutils import words, word_count


class T(unittest.TestCase):
    def test_words(self):
        self.assertEqual(words('a b'), ['a', 'b'])

    def test_word_count_basic(self):
        self.assertEqual(word_count('The cat, the HAT!'),
                         {'the': 2, 'cat': 1, 'hat': 1})

    def test_word_count_apostrophes_and_digits(self):
        self.assertEqual(word_count("Don't stop: 2 don't, 'quoted' 2"),
                         {"don't": 2, 'stop': 1, '2': 2, 'quoted': 1})

    def test_word_count_empty_and_punctuation_only(self):
        self.assertEqual(word_count(''), {})
        self.assertEqual(word_count("... ' !!"), {})

    def test_word_count_underscore_separates(self):
        self.assertEqual(word_count('a_b'), {'a': 1, 'b': 1})


if __name__ == '__main__':
    unittest.main()
"}

